Method.Implementation:
Quit:'$IsObject(pRequest.Stream) $$$ERROR($$$EnsErrGeneral,"No Stream contained in StreamContainer Request") Set tFilename=..Adapter.CreateTimestamp(##class(%File).GetFilename(pRequest.OriginalFilename),..Filename) Set tSC=..Adapter.PutStream(tFilename, pRequest.Stream) Do pRequest.%Save() ; re-save in case PutStream() optimization changed the Stream filename
// For this Retry logic to work, Operation Setting "Reply Code Actions" should have a code with R , e.g E=RD or E=RF $$$TRACE("Current Retry Count : "_..RetryCount) set MaxRetry = (..FailureTimeout/..RetryInterval)+1 $$$TRACE(..FailureTimeout_" **** "_..RetryInterval_" ***** "_"Max retry : "_MaxRetry) Set tFileName = ##class(%File).GetFilename(pRequest.OriginalFilename) _ " "
Set currentDate = $ZDATETIME($ZTIMESTAMP,3,3) Set extractDate = $EXTRACT(currentDate,0,11) Set extractTime = $EXTRACT(currentDate,11,$LENGTH(currentDate))
do ..valueToBeReplaced.SetAt(tFileName,"%FN") do ..valueToBeReplaced.SetAt(extractDate,"%CD") do ..valueToBeReplaced.SetAt(extractTime,"%CT")
Set updatedSuccessEmailSubject = ..replaceWithParticularFormat(..SuccessEmailSubject) Set updatedFailureEmailSubject = ..replaceWithParticularFormat(..FailureEmailSubject) Set updatedSuccessEmailbody = ..replaceWithParticularFormat(..SucessEmailBody) Set updatedFailureEmailbody = ..replaceWithParticularFormat(..FailureEmailBody)
//Sending Email If $$$ISOK(tSC) { $$$TRACE("Sending alert for successful file transfer.") do ..ItfSendEmailOnSuccess(updatedSuccessEmailSubject, updatedSuccessEmailbody) do ..valueToBeReplaced.SetAt("Success","%EM") } ElseIf(..RetryCount=MaxRetry) { $$$TRACE("Sending alert for failure in file transfer.") do ..valueToBeReplaced.SetAt(tSC,"%EM") do ..ItfSendEmailOnError(updatedFailureEmailSubject, updatedFailureEmailbody)
} Quit tSC
